@Override
    public void tick() {
        super.tick();
        if (invulnerableTime > 0) {
            invulnerableTime--;
        }
        if (warmup < VISUAL_WARMUP_TIME) {
            warmup++;
        }
        if (!level().isClientSide) {
            Entity victim = getVictim();
            if (victim == null || victim.isRemoved() || victim.distanceToSqr(this) > 12 * 12 || tickCount > lifetime || health <= 0) {
                breakChain();
                return;
            }
            applyRestraint(victim);
        } else {
            chainParticlesAround(this.position(), 3);
            if (parts != null && parts.length > 0) {
                chainParticlesAround(parts[parts.length - 1].position(), 1);
            }
        }

        repositionParts();
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        ArcaneShackleProjectile projectile = new ArcaneShackleProjectile(level, entity);
        projectile.setPos(entity.position().add(0, entity.getEyeHeight() - projectile.getBoundingBox().getYsize() * 0.5f, 0).add(entity.getForward()));
        projectile.shoot(entity.getLookAngle());
        projectile.setChainHealth(getChainHealth(spellLevel, entity));
        projectile.setChainLifetime(getChainDuration(spellLevel, entity));
        projectile.setLashRadius(getLashRadius(spellLevel, entity));
        projectile.setRestraintStrength(0.015f);
        level.addFreshEntity(projectile);
        level.playSound(null, entity.blockPosition(), SoundRegistry.THROW_DAGGER.get(),entity.getSoundSource(), 1f, 0.7f + entity.getRandom().nextFloat() * .1f);
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

@Override
    protected void onHitEntity(@NotNull EntityHitResult result) {
        super.onHitEntity(result);
        var entity = result.getEntity();
        LivingEntity victim;
        if (entity instanceof LivingEntity livingEntity) {
            victim = livingEntity;
        } else if (entity instanceof PartEntity<?> partEntity && partEntity.getParent() instanceof LivingEntity livingEntity) {
            victim = livingEntity;
        } else {
            victim = null;
        }
        if (!level.isClientSide && victim != null) {
            spawnChainsOnEntity(victim);
        }
        consumeEntityImpact(result, true);
    }

@Override
    protected void onHitBlock(@NotNull BlockHitResult result) {
        super.onHitBlock(result);
        if (!level.isClientSide) {
            Vec3 impactPos = result.getLocation();
            spawnChainsFromBlock(impactPos);
        }
        discard();
    }

private void spawnChainsOnEntity(LivingEntity victim) {
//        Vec3 forward = victim.getForward().yRot(60 * Mth.DEG_TO_RAD);
        Vec3 origin = victim.getBoundingBox().getCenter();

        float theta = Mth.TWO_PI / CHAIN_COUNT;
        for (int i = 0; i < CHAIN_COUNT; i++) {
            float angle = theta * i + Mth.TWO_PI / 4 - getYRot() * Mth.DEG_TO_RAD;
            float radius = lashRadius * 0.5f + victim.getBbWidth() * .4f;
            Vec3 direction = new Vec3(Mth.cos(angle) * radius, 0, Mth.sin(angle) * radius);
            Vec3 worldPos = Utils.moveToRelativeGroundLevel(victim.level, origin.add(direction), 2);
            if (level.noCollision(AABB.ofSize(worldPos, 0.5, 0.5, 0.5))) {
                Vec3 random = Utils.getRandomVec3(2);
                random = random.subtract(direction.scale(direction.normalize().dot(random.normalize())));
                worldPos = origin.add(direction).add(random);
            }
            spawnChain(victim, worldPos);
        }
    }

private void spawnChainsFromBlock(Vec3 impactPos) {
        // reduced radius on block hit
        float effectiveRadius = lashRadius;
        AABB searchBox = new AABB(impactPos, impactPos).inflate(lashRadius);
        List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, searchBox, entity ->
                (this.canHitEntity(entity) || entity.isMultipartEntity()) && distanceToSqr(entity) < effectiveRadius * effectiveRadius);
        entities.sort(Comparator.comparingDouble(e -> e.distanceToSqr(impactPos)));

        int count = Math.min(CHAIN_COUNT, entities.size());
        for (int i = 0; i < count; i++) {
            spawnChain(entities.get(i), impactPos);
        }
    }

private void spawnChain(LivingEntity victim, Vec3 anchor) {
        anchor = Utils.raycastForBlock(victim.level, this.position(), anchor, ClipContext.Fluid.ANY).getLocation();
        EnderChain chain = new EnderChain(level, getOwner(), victim, anchor);
        chain.setHealth(chainHealth);
        chain.setLifetime(chainLifetime);
        chain.setRestraintStrength(restraintStrength);
        level.addFreshEntity(chain);
    }

@Override
    public boolean hurt(@NotNull DamageSource source, float amount) {
        if (invulnerableTime > 0) {
            return false;
        }
        if (level().isClientSide || isInvulnerableTo(source)) {
            return false;
        }
        if (DamageSources.isFriendlyFireBetween(source.getEntity(), getOwner())) {
            return false;
        }
        health -= amount;
        if (health <= 0) {
            breakChain();
        } else {
            this.playSound(SoundEvents.CHAIN_STEP);
        }
        invulnerableTime = 10;
        return true;
    }

@Nullable
    public Entity getOwner() {
        if (this.cachedOwner != null && !this.cachedOwner.isRemoved()) {
            return this.cachedOwner;
        } else if (this.ownerUUID != null && this.level() instanceof ServerLevel serverLevel) {
            this.cachedOwner = serverLevel.getEntity(this.ownerUUID);
            return this.cachedOwner;
        }
        return null;
    }

@Nullable
    public Entity getVictim() {
        if (this.cachedVictim != null && !this.cachedVictim.isRemoved()) {
            return this.cachedVictim;
        } else if (this.victimUUID != null && this.level() instanceof ServerLevel serverLevel) {
            Entity e = serverLevel.getEntity(this.victimUUID);
            if (e instanceof LivingEntity living) {
                this.cachedVictim = living;
                return living;
            }
        }
        return null;
    }

private void applyRestraint(Entity victim) {
        Vec3 displacement = victim.position().subtract(position());
        if (displacement.lengthSqr() < 1.0E-8) {
            return;
        }
        Vec3 deltaV = displacement.scale(-restraintStrength);
        deltaV.multiply(deltaV);
        victim.setDeltaMovement(victim.getDeltaMovement().add(deltaV));
        victim.hurtMarked = true;
        if (victim.getDeltaMovement().y >= 0) {
            victim.resetFallDistance();
        }
    }

public void breakChain() {
        if (!level().isClientSide) {
            playSound(SoundEvents.CHAIN_BREAK);
            if (parts.length > 0) {
                int count = 15;
                Vec3 pos = position();
                Vec3 end = parts[parts.length - 1].position();
                for (int i = 0; i < count; i++) {
                    Vec3 vec3 = pos.lerp(end, i / (float) count);
                    MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, vec3.x, vec3.y, vec3.z, 1, 0.05, 0.05, 0.05, 0.1, false);
                }
            }
            this.discard();
        }
    }

@Override
    public void onAntiMagic(MagicData playerMagicData) {
        breakChain();
    }

