        var owner = getOwner();
        buffer.writeInt(owner == null ? 0 : owner.getId());
        var victim = getVictim();
        buffer.writeInt(victim == null ? 0 : victim.getId());
    }

@Override
    public void readSpawnData(RegistryFriendlyByteBuf additionalData) {
        Entity owner = this.level.getEntity(additionalData.readInt());
        if (owner != null) {
            this.setOwner(owner);
        }
        Entity victim = this.level.getEntity(additionalData.readInt());
        if (victim != null) {
            this.cachedVictim = victim;
            this.victimUUID = victim.getUUID();
        }
    }

@Override
    public boolean hurt(@NotNull DamageSource source, float amount) {
        if (!level.isClientSide) {
            MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, getBoundingBox().getCenter().x, getBoundingBox().getCenter().y, getBoundingBox().getCenter().z, 3, 0, 0, 0, 0.15, false);
        }
        return parentChain.hurt(source, amount);
    }
